class Solution {
public:
    int maxSum(vector<int>& nums) {
        vector<int> best(10, -1);
        int ans = -1;
        for (int v : nums) {
            int temp = v, max_d = 0;
            while (temp > 0) {
                max_d = max(max_d, temp % 10);
                temp /= 10;
            }
            if (best[max_d] != -1) {
                ans = max(ans, best[max_d] + v);
            }
            best[max_d] = max(best[max_d], v);
        }
        return ans;
    }
};

import java.util.*;

class Solution {
    public int maxSum(int[] nums) {
        int[] best = new int[10];
        Arrays.fill(best, -1);
        int ans = -1;
        for (int v : nums) {
            int temp = v, maxD = 0;
            while (temp > 0) {
                maxD = Math.max(maxD, temp % 10);
                temp /= 10;
            }
            if (best[maxD] != -1) {
                ans = Math.max(ans, best[maxD] + v);
            }
            best[maxD] = Math.max(best[maxD], v);
        }
        return ans;
    }
}

