var maxSum = function(nums) {
    const best = new Array(10).fill(-1);
    let ans = -1;
    for (const v of nums) {
        let temp = v, maxD = 0;
        while (temp > 0) {
            maxD = Math.max(maxD, temp % 10);
            temp = Math.floor(temp / 10);
        }
        if (best[maxD] !== -1) {
            ans = Math.max(ans, best[maxD] + v);
        }
        best[maxD] = Math.max(best[maxD], v);
    }
    return ans;
};
